 private Path directory;private JsonObject inputs;private String mode;private boolean opening,queued,initialized,done,capturing;private volatile boolean ready,captured;private volatile Throwable failure;private int checks,scene,ticks;private NaturalScenery.Table natural,oldTable;private volatile Vec3 destination;private volatile float yaw,pitch;private volatile BlockPos sample;private volatile BlockState sampleState;
