 private void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError("Iblp0616: "+why);}
 private static String digest(String text)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8)));}
 private static String signature(NotationCatalog.Iblp p){return new Gson().toJson(p);}
 @Override public void onInitializeClient(){directory=FabricLoader.getInstance().getGameDir();if(!Boolean.getBoolean("guogaology.iblp0616")||!Files.isRegularFile(directory.resolve("iblp0616-inputs.json")))throw new IllegalStateException("Explicit own disposable runner required");try{inputs=JsonParser.parseString(Files.readString(directory.resolve("iblp0616-inputs.json"))).getAsJsonObject();}catch(Exception e){throw new RuntimeException(e);}mode=inputs.get("mode").getAsString();ClientTickEvents.END_CLIENT_TICK.register(this::tick);}
 private void catalog()throws Exception{
  var all=NotationCatalog.allIblp();int expected=inputs.get("expectedCatalogCount").getAsInt();check(all.size()==expected,"exact loaded production catalog count");check(NotationCatalog.allBms().size()==1070,"all1070 original BMS retained");
  var sizes=new TreeMap<Integer,Integer>();var signatures=new HashSet<String>();long cells=0;int maxStep=0;
  for(var p:all){int n=p.size();sizes.merge(n,1,Integer::sum);check(n>=1&&n<=69&&p.steps().length==n&&p.marks().length==n,"complete row/step/mark structure");check(signatures.add(signature(p)),"no duplicate complete catalog records");
   for(int r=1;r<=n;r++){int[] occupied=p.rows()[r-1],marked=p.marks()[r-1];for(int i=1;i<occupied.length;i++)check(occupied[i]>occupied[i-1],"sorted unique occupied columns");for(int i=1;i<marked.length;i++)check(marked[i]>marked[i-1],"sorted unique marked columns");for(int c:marked)check(Arrays.binarySearch(occupied,c)>=0,"marked cell is occupied");
    check(p.steps()[r-1]>=0&&p.steps()[r-1]<=15,"native numeric terminal range");maxStep=Math.max(maxStep,p.steps()[r-1]);var occupiedSet=new HashSet<Integer>();for(int c:occupied)occupiedSet.add(c);var markedSet=new HashSet<Integer>();for(int c:marked)markedSet.add(c);for(int c=-1;c<=n+1;c++){int desired=occupiedSet.contains(c)?markedSet.contains(c)?2:1:0;check(p.cell(r,c)==desired,"actual cell API equals source row and mark membership");cells++;}
   }check(p.cell(0,0)==0&&p.cell(n+1,0)==0,"out-of-range rows are blank");
  }
  for(int n=1;n<=69;n++)check(sizes.getOrDefault(n,0)>0,"all69 source sizes retained "+n);for(int n=4;n<=69;n++){final int size=n;check(all.stream().anyMatch(p->p.size()==size),"TABLES retains every4..69 size "+n);}
  var sampledSizes=new TreeSet<Integer>();for(long seed=0;seed<4096;seed++){var p=NotationCatalog.table(WorldNoise.mix(seed+616));check(signature(p).equals(signature(NotationCatalog.table(WorldNoise.mix(seed+616)))),"seed table selector deterministic");check(p.size()>=4&&p.size()<=69&&signatures.contains(signature(p)),"table selector only uses complete retained records");sampledSizes.add(p.size());}
  check(sampledSizes.size()==66,"public table selector reaches every retained4..69 size in bounded deterministic samples");if(expected==1000)check(maxStep>=11,"selected library retains high-step examples");
  for(int limit:new int[]{10,30,100})for(long seed=-32;seed<32;seed++){var p=NotationCatalog.iblp(seed,limit);check(signature(p).equals(signature(NotationCatalog.iblp(seed,limit)))&&signatures.contains(signature(p)),"legacy small/medium/all selector stable and retains complete data");check(limit>30||p.size()<=limit,"small/medium selector respects size");}
  var meta=new JsonObject();meta.addProperty("loadedPatterns",all.size());meta.addProperty("bmsPatterns",1070);meta.add("patternsBySize",GSON.toJsonTree(sizes));meta.addProperty("verifiedCells",cells);meta.addProperty("maximumStep",maxStep);meta.addProperty("deterministicSeedSamples",4096);meta.add("sampledTableSizes",GSON.toJsonTree(sampledSizes));meta.addProperty("bmsCanonicalSha256",digest(new Gson().toJson(NotationCatalog.allBms())));meta.addProperty("courtPatternsCanonicalSha256",digest(new Gson().toJson(CourtLaverPatterns.ALL)));result.add("catalog",meta);
 }
 private void palace(){var layout=SanctuaryLayout.of(SurvivalTheme.WEAVER);int tables=0,cores=0;for(var f:layout.furnishings())if(f.kind().startsWith("playable_iblp_")){tables++;var pattern=Arrays.stream(CourtLaverPatterns.ALL).filter(p->f.kind().equals("playable_iblp_"+p.name())).findFirst().orElseThrow();int n=pattern.rows().length,o=n/2;for(int r=0;r<=n;r++)for(int c=-1;c<=r+1;c++){int expected=SanctuaryLayout.LAVER_INLAY;if(c>=0&&c<=r)expected=r==0?SanctuaryLayout.LAVER_CORE:Arrays.binarySearch(pattern.rows()[r-1],c)<0?SanctuaryLayout.COURT_BLANK:Arrays.binarySearch(pattern.marks()[r-1],c)>=0?SanctuaryLayout.LAVER_CORE:SanctuaryLayout.COURT_NODE;check(layout.at(f.floor().x()+c-o,f.floor().y()+3,f.floor().z()+r-o)==expected,"fixed palace original pattern cells/core locations");if(expected==SanctuaryLayout.LAVER_CORE)cores++;}}
  check(tables==4&&cores==5,"four original palace patterns/five pattern cores");check(layout.interiorResources().stream().filter(SanctuaryLayout.InteriorResource::regional).count()==8,"eight palace regional exhibits retained");result.addProperty("fixedPalacePatterns",4);
 }
 private static Map<BlockPos,BlockState> paint(NaturalScenery.Table t)throws Exception{var map=new LinkedHashMap<BlockPos,BlockState>();var m=NaturalScenery.class.getDeclaredMethod("table",SceneryBrush.class,NaturalScenery.Table.class);m.setAccessible(true);m.invoke(null,new SceneryBrush(t.site().x()-80,t.site().x()+80,t.site().z()-80,t.site().z()+80,(x,y,z,s)->map.put(new BlockPos(x,y,z),s)),t);return map;}
 private void prime(ServerLevel w,NaturalScenery.Table t){int n=t.pattern().size(),r=n+5;for(int cx=Math.floorDiv(t.site().x()-r,16);cx<=Math.floorDiv(t.site().x()+r,16);cx++)for(int cz=Math.floorDiv(t.site().z()-r,16);cz<=Math.floorDiv(t.site().z()+r,16);cz++)check(w.getChunk(cx,cz).getPersistedStatus()==ChunkStatus.FULL,"actual completed native FULL table neighbourhood");}
 private JsonArray rows(ServerLevel w,NaturalScenery.Table t){var result=new JsonArray();for(int r=1;r<=t.pattern().size();r++){var start=NaturalScenery.tableCell(t,r,-1);var row=LiveLaverTable.read(w,start);check(row!=null&&row.end().equals(NaturalScenery.tableCell(t,r,r+1))&&row.notes().size()==r+1,"real complete generated row can be read");check(row.step()==t.pattern().steps()[r-1]&&row.duration()==5*(r+1)&&row.valid(w),"row step/quarter-second duration/live validity");var out=new JsonObject();out.addProperty("row",r);out.addProperty("step",row.step());out.addProperty("duration",row.duration());var notes=new JsonArray();for(int c=0;c<=r;c++){var note=row.notes().get(c);check(note.kind()==t.pattern().cell(r,c)&&note.tick()==c*5,"real source cells/marks/rests and5-tick offsets");var v=new JsonObject();v.addProperty("kind",note.kind());v.addProperty("tick",note.tick());v.addProperty("semitone",note.semitone());v.addProperty("marked",note.marked());notes.add(v);}out.add("notes",notes);result.add(out);}return result;}
 private void play(ServerPlayer p,ServerLevel w,NaturalScenery.Table t){var pos=NaturalScenery.tableCell(t,t.pattern().size(),-1);var oldPos=p.position();var oldWorld=p.level();check(oldWorld==w,"play callback uses actual player's dimension");p.setPos(Vec3.atCenterOf(pos));p.setShiftKeyDown(false);var hit=new BlockHitResult(Vec3.atCenterOf(pos),Direction.UP,pos,false);check(UseBlockCallback.EVENT.invoker().interact(p,w,InteractionHand.MAIN_HAND,hit)==InteractionResult.SUCCESS&&LaverMusic.activeCount(w)==1,"real native inlay callback starts playback");check(UseBlockCallback.EVENT.invoker().interact(p,w,InteractionHand.MAIN_HAND,hit)==InteractionResult.SUCCESS&&LaverMusic.activeCount(w)==0,"same inlay stops without block changes");p.setPos(oldPos);}
 private void orientations(ServerPlayer p)throws Exception{var w=p.level();var pattern=NotationCatalog.allIblp().stream().filter(t->t.size()==6).findFirst().orElseThrow();var saved=new HashMap<BlockPos,BlockState>();for(int turn=0;turn<4;turn++)for(boolean mirror:new boolean[]{false,true})for(boolean vertical:new boolean[]{false,true}){var t=new NaturalScenery.Table(new NaturalScenery.Site(616025,16,40,40,4,240,Integer.MIN_VALUE,false),pattern,246,turn,vertical,mirror);prime(w,t);var map=paint(t);try{for(var e:map.entrySet()){saved.put(e.getKey(),w.getBlockState(e.getKey()));w.setBlock(e.getKey(),e.getValue(),FLAGS);}rows(w,t);}finally{for(var e:saved.entrySet())w.setBlock(e.getKey(),e.getValue(),FLAGS);saved.clear();}}result.addProperty("nativeTableOrientations",16);}
 private JsonObject fingerprint(ServerLevel w,int cx,int cz)throws Exception{var chunk=w.getChunk(cx,cz);check(chunk.getPersistedStatus()==ChunkStatus.FULL,"fingerprinted native FULL chunk");var md=MessageDigest.getInstance("SHA-256");var cache=new IdentityHashMap<BlockState,byte[]>();var pos=new BlockPos.MutableBlockPos();for(int x=0;x<16;x++)for(int z=0;z<16;z++)for(int y=w.getMinY();y<w.getMaxY();y++){var s=chunk.getBlockState(pos.set(cx*16+x,y,cz*16+z));md.update(cache.computeIfAbsent(s,v->(v.toString()+"\n").getBytes(StandardCharsets.UTF_8)));}var row=new JsonObject();row.addProperty("chunkX",cx);row.addProperty("chunkZ",cz);row.addProperty("allBlockStatesSha256",HexFormat.of().formatHex(md.digest()));return row;}
 private JsonObject tableData(NaturalScenery.Table t,JsonArray music){var row=new JsonObject();row.add("table",GSON.toJsonTree(t));row.add("music",music);return row;}
 private static NaturalScenery.Table tableData(JsonObject row){return GSON.fromJson(row.get("table"),NaturalScenery.Table.class);}
 private void baseline(ServerPlayer p)throws Exception{var w=p.level();var retained=new HashSet<String>();for(var id:inputs.getAsJsonArray("retainedExpressionKeys"))retained.add(id.getAsString());var pattern=NotationCatalog.allIblp().stream().filter(t->t.size()==6&&!retained.contains(t.sourceRow()+"|"+t.expression())).findFirst().orElseThrow();oldTable=new NaturalScenery.Table(new NaturalScenery.Site(616025,1,5128,5128,4,240,Integer.MIN_VALUE,false),pattern,250,0,false,false);prime(w,oldTable);for(var pos:BlockPos.betweenClosed(new BlockPos(5121,249,5121),new BlockPos(5135,252,5135)))w.setBlock(pos,Blocks.AIR.defaultBlockState(),FLAGS);for(var e:paint(oldTable).entrySet())w.setBlock(e.getKey(),e.getValue(),FLAGS);var oldRows=rows(w,oldTable);play(p,w,oldTable);w.getChunk(321,320);var chunks=new JsonArray();chunks.add(fingerprint(w,320,320));chunks.add(fingerprint(w,321,320));var manifest=new JsonObject();manifest.addProperty("fixtureOnly",true);manifest.addProperty("producerVersion","0.6.15");manifest.add("chunks",chunks);manifest.add("oldRemovedTable",tableData(oldTable,oldRows));manifest.add("catalog",result.get("catalog"));Files.writeString(directory.resolve(MANIFEST),GSON.toJson(manifest)+"\n",StandardOpenOption.CREATE_NEW);check(w.getServer().saveEverything(false,true,true),"genuine old FULL fixture saved to disk");result.add("baseline",manifest);}
 private void upgrade(ServerPlayer p)throws Exception{var old=JsonParser.parseString(Files.readString(directory.resolve(MANIFEST))).getAsJsonObject();check(old.get("fixtureOnly").getAsBoolean()&&old.get("producerVersion").getAsString().equals("0.6.15"),"known old disposable producer");var verified=new JsonArray();for(var e:old.getAsJsonArray("chunks")){var expected=e.getAsJsonObject();var current=fingerprint(p.level(),expected.get("chunkX").getAsInt(),expected.get("chunkZ").getAsInt());check(current.equals(expected),"every block state of genuinely old FULL chunk unchanged");verified.add(current);}oldTable=tableData(old.getAsJsonObject("oldRemovedTable"));check(NotationCatalog.allIblp().stream().noneMatch(t->t.sourceRow()==oldTable.pattern().sourceRow()&&t.expression().equals(oldTable.pattern().expression())),"old saved table deliberately uses a now-removed source record");prime(p.level(),oldTable);check(rows(p.level(),oldTable).equals(old.getAsJsonObject("oldRemovedTable").getAsJsonArray("music")),"removed-record old physical table preserves exact steps/rests/marks/notes/music");play(p,p.level(),oldTable);check(result.getAsJsonObject("catalog").get("bmsCanonicalSha256").equals(old.getAsJsonObject("catalog").get("bmsCanonicalSha256"))&&result.getAsJsonObject("catalog").get("courtPatternsCanonicalSha256").equals(old.getAsJsonObject("catalog").get("courtPatternsCanonicalSha256")),"original BMS and palace serialized values unchanged across upgrade");result.add("oldFullChunksPreserved",verified);result.addProperty("removedOldTablePhysicalAndMusicPreserved",true);}
 private void natural(ServerPlayer p)throws Exception{var w=p.level().getServer().getLevel(GuogaologyMod.DIMENSION);check(w!=null,"registered actual inner dimension");long seed=ProceduralTerrain.seed(w.getChunkSource().randomState());var pass=SceneryDistribution.passes(false).stream().filter(t->t.form()==SceneryDistribution.Form.TABLE).findFirst().orElseThrow();int centerX=0,centerZ=0,best=-1,proposals=0;for(int x=-10;x<=10;x++)for(int z=-10;z<=10;z++){int wx=32768+x*464,wz=32768+z*464,score=0;for(int dx:new int[]{-180,0,180})for(int dz:new int[]{-180,0,180})if(BiomeRegions.kind(seed,wx+dx,wz+dz)==4)score++;if(score>best){best=score;centerX=wx;centerZ=wz;}}check(best>=5,"bounded pure search locates inner Laver plateau");
  outer:for(int radius=0;radius<=18;radius++)for(int dx=-radius;dx<=radius;dx++)for(int dz=-radius;dz<=radius;dz++){if(Math.max(Math.abs(dx),Math.abs(dz))!=radius)continue;var source=NaturalScenery.site(seed,pass.cell(),Math.floorDiv(centerX,pass.cell())+dx,Math.floorDiv(centerZ,pass.cell())+dz,false);if(!pass.accepts(source.kind(),source.salt())||source.floor()==Integer.MIN_VALUE)continue;proposals++;var chosen=NotationCatalog.table(source.salt());if(chosen.size()>16)continue;var site=SceneryPlacement.resolve(source,pass);if(site==null||!NaturalScenery.tablePresent(site))continue;var t=NaturalScenery.table(site);if(t.base()==Integer.MIN_VALUE||t.vertical())continue;natural=t;break outer;}
  check(natural!=null,"bounded natural planner retains a complete manageable Laver table");var expected=paint(natural);for(var q:expected.keySet())check(w.getChunkSource().getChunkNow(q.getX()>>4,q.getZ()>>4)==null,"new natural scene has no preexisting FULL chunk");prime(w,natural);int checked=0;for(int r=1;r<=natural.pattern().size();r++)for(int c=-1;c<=r+1;c++){var q=NaturalScenery.tableCell(natural,r,c);check(w.getBlockState(q).equals(expected.get(q)),"actual fresh FULL generation emitted exact complete current catalog cells/step/inlay");checked++;}var music=rows(w,natural);var proof=tableData(natural,music);proof.addProperty("plannerProposalsExamined",proposals);proof.addProperty("verifiedDiagramCells",checked);proof.addProperty("actualFreshFullNativeGeneration",true);result.add("newNaturalFullTable",proof);System.out.println("IBLP0616_NATURAL_OK site="+natural.site()+" size="+natural.pattern().size());}
 @FunctionalInterface private interface Action{void run(ServerPlayer p)throws Exception;}
 private void queue(Minecraft c,Action task){queued=true;ready=false;ticks=0;var id=c.player.getUUID();c.getSingleplayerServer().execute(()->{try{task.run(c.getSingleplayerServer().getPlayerList().getPlayer(id));ready=true;}catch(Throwable e){failure=e;}});}
 private void initial(ServerPlayer p)throws Exception{String version=FabricLoader.getInstance().getModContainer("guogaology").orElseThrow().getMetadata().getVersion().getFriendlyString();check(version.equals(inputs.get("productionVersion").getAsString()),"exact staged production release");result.addProperty("productionVersion",version);p.level().getServer().tickRateManager().setFrozen(true);p.level().getServer().getGameRules().set(GameRules.RANDOM_TICK_SPEED,0,p.level().getServer());p.setGameMode(GameType.CREATIVE);p.getInventory().clearContent();p.closeContainer();catalog();palace();if(mode.equals("baseline0615")){check(version.equals("0.6.15"),"baseline exact old producer");baseline(p);return;}if(mode.equals("upgrade"))upgrade(p);orientations(p);natural(p);}
 private void display(ServerPlayer p,int index)throws Exception{var t=index==0?natural:oldTable;var w=index==0?p.level().getServer().getLevel(GuogaologyMod.DIMENSION):p.level().getServer().overworld();int n=t.pattern().size();var center=NaturalScenery.tableCell(t,n/2,n/3);Vec3 target=Vec3.atCenterOf(center);Vec3 eye=target.add(n*.9+5,n*.8+4,n*.9+5);var delta=target.subtract(eye);yaw=(float)Math.toDegrees(Math.atan2(-delta.x,delta.z));pitch=(float)-Math.toDegrees(Math.atan2(delta.y,Math.hypot(delta.x,delta.z)));destination=eye.add(0,-1.62,0);sample=NaturalScenery.tableCell(t,n,0);sampleState=w.getBlockState(sample);p.teleport(new TeleportTransition(w,destination,Vec3.ZERO,yaw,pitch,TeleportTransition.DO_NOTHING));p.noPhysics=true;p.setNoGravity(true);p.getAbilities().flying=true;p.onUpdateAbilities();}
 private void tick(Minecraft c){if(done)return;try{if(failure!=null)throw new RuntimeException(failure);if(System.nanoTime()>deadline)throw new AssertionError("iblp0616 timeout");c.options.pauseOnLostFocus=false;c.options.renderDistance().set(5);c.options.fov().set(60);c.getTutorial().setStep(net.minecraft.client.tutorial.TutorialSteps.NONE);c.gui.toastManager().clear();if(!c.gui.hud.isHidden())c.gui.hud.toggle();if(c.level==null){if(!opening&&c.isGameLoadFinished()&&c.gui.overlay()==null){opening=true;if(mode.equals("upgrade")){check(Files.isRegularFile(directory.resolve(MANIFEST)),"known staged manifest only");c.createWorldOpenFlows().openWorld(WORLD,c::stop);}else{check(!Files.exists(directory.resolve("saves").resolve(WORLD)),"fresh own world only");var settings=new LevelSettings("iBLP0616 isolated QA",GameType.CREATIVE,LevelSettings.DifficultySettings.DEFAULT,true,WorldDataConfiguration.DEFAULT);c.createWorldOpenFlows().createFreshLevel(WORLD,settings,new WorldOptions(616025L,true,false),r->r.lookupOrThrow(Registries.WORLD_PRESET).getOrThrow(WorldPresets.FLAT).value().createWorldDimensions(),new TitleScreen());}}return;}if(c.player==null||c.getSingleplayerServer()==null||c.gui.overlay()!=null)return;if(!initialized){if(!queued){queue(c,this::initial);return;}if(!ready)return;initialized=true;queued=false;}if(!ready)return;int photoCount=Boolean.getBoolean("guogaology.iblp0616.focused")||mode.equals("baseline0615")?0:mode.equals("upgrade")?2:1;if(scene==photoCount){finish(c);return;}if(!queued){queue(c,p->display(p,scene));return;}if(!ready||c.player.position().distanceToSqr(destination)>.25)return;var expectedDim=scene==0?GuogaologyMod.DIMENSION:Level.OVERWORLD;if(!c.level.dimension().equals(expectedDim)||!c.level.getBlockState(sample).equals(sampleState)){if(++ticks>600)throw new AssertionError("native photo dimension/cells not synchronized");return;}if(c.gui.screen() instanceof LevelLoadingScreen){c.gui.setScreen(null);ticks=0;return;}if(c.gui.screen()!=null||c.gui.overlay()!=null){ticks=0;return;}c.player.setYRot(yaw);c.player.yRotO=yaw;c.player.setYHeadRot(yaw);c.player.setXRot(pitch);c.player.xRotO=pitch;if(++ticks<100)return;if(!capturing){check(!c.mouseHandler.isMouseGrabbed(),"hidden native client never grabs mouse");String name="iblp0616-"+(scene==0?"new-natural-full-table":"old-removed-record-table-preserved")+".png";Files.createDirectories(directory.resolve("screenshots"));capturing=true;Screenshot.takeScreenshot(c.gameRenderer.mainRenderTarget(),image->{try(image){image.writeToFile(directory.resolve("screenshots").resolve(name));captured=true;}catch(Throwable e){failure=e;}});pictures.add(name);return;}if(captured){scene++;queued=ready=capturing=captured=false;ticks=0;ready=true;}}
 catch(Throwable e){done=true;e.printStackTrace();try{Files.writeString(directory.resolve("iblp0616-failed.txt"),e.toString());Files.writeString(directory.resolve("iblp0616-partial.json"),GSON.toJson(result));}catch(Exception ignored){}c.stop();}}
 private void finish(Minecraft c)throws Exception{result.addProperty("success",true);result.addProperty("mode",mode);result.addProperty("minecraft",inputs.get("minecraft").getAsString());result.addProperty("checks",checks);result.add("inputs",inputs);result.add("screenshots",pictures);result.addProperty("scope",mode.equals("baseline0615")?"Exact0615 catalog and native production painter create an authored old removed-record table in actual FULL chunks of an own disposable save. Two complete block-state hashes and every row/music detail saved; this phase is not the new1000-catalog test.":"Actual new catalog APIs, source-cell integrity and bounded deterministic selection checks; fixed palace patterns;16native painter orientations and full live row readers; actual fresh FULL native inner-world generation of one complete naturally planned table. Upgrade additionally reopens two old FULL disk chunks and the deliberately removed-record old physical table with exact music. Not a natural-density census, all user-save certification, or claim that new chunk patterns preserve their old source choice.");Files.writeString(directory.resolve("iblp0616-results.json"),GSON.toJson(result)+"\n",StandardOpenOption.CREATE_NEW);Files.writeString(directory.resolve("iblp0616-ok.txt"),"IBLP0616_NATIVE_OK checks="+checks+"\n",StandardOpenOption.CREATE_NEW);done=true;c.stop();}
